  const shell=(children)=><div className="min-h-screen bg-slate-50 text-slate-900 font-sans"><main className="max-w-lg mx-auto p-4 pb-28 space-y-5"><header className="flex justify-between items-start gap-2 mb-2 pt-2"><div><div className="flex flex-wrap items-center gap-2"><h1 className="text-2xl font-extrabold text-slate-800">{data.code?`${L('Merhaba','Hello')}, ${data.code}!`:L('Hoş geldin','Welcome')}</h1>{data.code&&<span className="text-[11px] font-bold px-2.5 py-0.5 rounded-full bg-indigo-100 text-indigo-700">{data.group===1?'Grup A':'Grup B'}</span>}</div><p className="text-xs text-slate-500 mt-1">{L('Verilerin cihazına otomatik kaydediliyor.','Your data is saved locally on your device.')}</p>{data.code&&<p className="text-[11px] text-slate-500 mt-1">{data.start?`${data.start} – ${end}`:L("21 gün ilk hedefini kaydettiğinde başlayacak.","Your 21 days begin when you save your first goal.")}</p>}</div>{langToggle}</header>{notices}{children}</main></div>;
